import SwiftUI

/// «Дневник (PDF)» (#246, #436): «ДНЕВНИК НА СТОПАНСТВОТО» for a campaign,
/// generated by the server and opened in Quick Look, where it can be read,
/// shared or saved to Files.
///
/// The owner's own template (2026-10-25): the whole farm, every recorded
/// activity, by campaign (1 October to 30 September). It replaced the БАБХ
/// ДНЕВНИК for a block and a period. The БАБХ register stays per treatment
/// («Изтегли PDF» on its entry), so there is no block to choose here, and no
/// dates. The campaigns are worked out on the phone (`FarmRecordAPI.Campaign`),
/// the current one first.
struct FarmRecordSheet: View {
    @Environment(\.dismiss) private var dismiss
    @State private var campaign = FarmRecordAPI.Campaign.containing(Date())
    @State private var generating = false
    @State private var failure: String?
    /// Nothing recorded in the campaign: not a failure, so a plain note,
    /// gone once the question changes.
    @State private var nothingRecorded = false
    /// The PDF, once generated: what Quick Look shows. Removed when the
    /// sheet closes, by its presenter (`FarmRecordAPI.removeGenerated`).
    @State private var document: URL?

    private let campaigns = FarmRecordAPI.Campaign.recent()

    static let campaignNote =
        "Всички дейности на стопанството от 1 октомври до 30 септември: мероприятия, резитба, обработки и реколта."

    var body: some View {
        NavigationStack {
            PageForm {
                Section {
                    MenuPicker("Кампания", selection: $campaign, value: Self.years(campaign)) {
                        ForEach(campaigns) { Text(Self.years($0)).tag($0) }
                    }
                } footer: {
                    SectionFooter {
                        // Hyphenated where AX5 has to break its first word
                        // (`SoftHyphens`); spoken as written.
                        Text(SoftHyphens.display(Self.campaignNote))
                            .accessibilityLabel(Self.campaignNote)
                    }
                }

                if nothingRecorded {
                    Section {
                        Label(FarmRecordAPI.emptyCampaignText, systemImage: "doc.text.magnifyingglass")
                            .foregroundStyle(Palette.secondaryText)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                } else if let failure {
                    Section {
                        Text(failure)
                            .foregroundStyle(Palette.error)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
            }
            .inlineTitle("Дневник (PDF)")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Отказ") { dismiss() }
                        .accessibilityInputLabels(A11y.Spoken.cancel)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button {
                        Task { await generate() }
                    } label: {
                        if generating { ProgressView() } else { Text("Изтегли") }
                    }
                    .disabled(generating)
                    .accessibilityLabel("Изтегли")
                    .accessibilityInputLabels(A11y.Spoken.download)
                }
            }
            .quickLookPreview($document)
            // A note about one campaign says nothing about another.
            .onChange(of: campaign) { nothingRecorded = false; failure = nil }
        }
    }

    /// «2024–2025» in the menu, under its «Кампания» title.
    nonisolated static func years(_ campaign: FarmRecordAPI.Campaign) -> String {
        "\(campaign.startYear)–\(campaign.startYear + 1)"
    }

    /// A campaign's rows are uncapped, so the server may take a while; the
    /// document session waits (`APIClient.postForDocument`), the button turns
    /// into a spinner and the sheet stays.
    private func generate() async {
        guard !generating else { return }
        generating = true
        failure = nil
        nothingRecorded = false
        defer { generating = false }
        do {
            document = try await FarmRecordAPI.generate(campaign)
        } catch let error where FarmRecordAPI.isEmptyPeriod(error) {
            nothingRecorded = true
            AccessibilityNotification.Announcement(FarmRecordAPI.emptyCampaignText).post()
        } catch let refused as FarmRecordAPI.Failure {
            failure = refused.errorDescription
        } catch {
            failure = UserMessage.text(for: error)
        }
    }
}
